<script>
const addItemToggle=document.getElementById('toggleAddItem'),addItemForm=document.getElementById('addItemForm'),addItemCancel=document.getElementById('cancelAddItem');if(addItemToggle&&addItemForm){addItemToggle.addEventListener('click',()=>{addItemForm.hidden=!addItemForm.hidden;addItemToggle.setAttribute('aria-expanded',String(!addItemForm.hidden));addItemToggle.innerHTML=addItemForm.hidden?'<i class="fas fa-plus"></i> Neuen Artikel anlegen':'<i class="fas fa-times"></i> Formular schließen';});}if(addItemCancel&&addItemForm&&addItemToggle){addItemCancel.addEventListener('click',()=>{addItemForm.hidden=true;addItemToggle.setAttribute('aria-expanded','false');addItemToggle.innerHTML='<i class="fas fa-plus"></i> Neuen Artikel anlegen';});}const editToggle=document.getElementById('toggleActionEdit'),editForm=document.getElementById('actionEditForm'),editCancel=document.getElementById('cancelActionEdit');if(editToggle&&editForm){editToggle.addEventListener('click',()=>{editForm.hidden=!editForm.hidden;editToggle.setAttribute('aria-expanded',String(!editForm.hidden));editToggle.innerHTML=editForm.hidden?'<i class="fas fa-pen"></i>':'<i class="fas fa-times"></i>';editToggle.title=editForm.hidden?'Verkaufsaktion bearbeiten':'Bearbeiten schließen';});}if(editCancel&&editForm&&editToggle){editCancel.addEventListener('click',()=>{editForm.hidden=true;editToggle.setAttribute('aria-expanded','false');editToggle.innerHTML='<i class="fas fa-pen"></i>';editToggle.title='Verkaufsaktion bearbeiten';});}
